class FakeDownloader(private val failureRate: Double, private val random: Random = Random.Default) {
    fun download(name: String): Flow<Int> = flow {
        for (percent in 0..100 step 5) {
            if (percent == 50 && random.nextDouble() < failureRate) throw IOException("Connection lost")
            emit(percent)
            delay(100)
        }
    }
}
